import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  Boxes,
  Search,
  RefreshCw,
  ChevronLeft,
  ChevronRight,
  Hash,
  Warehouse,
  Calendar,
  DollarSign,
  Package,
  AlertTriangle,
  Tag,
  Building2,
  BarChart3,
} from "lucide-react";
import { queryClient } from "@/lib/queryClient";
import { useState } from "react";
import type { InventoryRow, InventoryListResult, InventoryStats } from "@shared/schema";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, ResponsiveContainer, Tooltip, Cell } from "recharts";

function formatDate(dateStr: string | null): string {
  if (!dateStr) return "-";
  const d = new Date(dateStr);
  return d.toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function DetailRow({
  icon: Icon,
  label,
  value,
  testId,
}: {
  icon: any;
  label: string;
  value: string | number | null;
  testId: string;
}) {
  return (
    <div className="flex items-start gap-3 py-2">
      <Icon className="w-4 h-4 text-muted-foreground mt-0.5 shrink-0" />
      <div className="flex-1 min-w-0">
        <p className="text-xs text-muted-foreground">{label}</p>
        <p className="text-sm font-medium break-all" data-testid={testId}>
          {value ?? "-"}
        </p>
      </div>
    </div>
  );
}

function StockBadge({ available }: { available: number }) {
  if (available === 0) {
    return <Badge variant="destructive" className="text-[10px]">Out of Stock</Badge>;
  }
  if (available <= 5) {
    return <Badge variant="outline" className="text-[10px] border-amber-500 text-amber-600 dark:text-amber-400">Low Stock</Badge>;
  }
  return <Badge variant="outline" className="text-[10px] border-emerald-500 text-emerald-600 dark:text-emerald-400">In Stock</Badge>;
}

export default function Inventory() {
  const [search, setSearch] = useState("");
  const [searchInput, setSearchInput] = useState("");
  const [warehouse, setWarehouse] = useState("");
  const [stockLevel, setStockLevel] = useState("");
  const [page, setPage] = useState(0);
  const [selectedItem, setSelectedItem] = useState<InventoryRow | null>(null);
  const limit = 50;

  const { data: stats, isLoading: statsLoading } = useQuery<InventoryStats>({
    queryKey: ["/api/inventory/stats"],
  });

  const queryParams = new URLSearchParams();
  queryParams.set("limit", String(limit));
  queryParams.set("offset", String(page * limit));
  if (search) queryParams.set("search", search);
  if (warehouse) queryParams.set("warehouse", warehouse);
  if (stockLevel) queryParams.set("stockLevel", stockLevel);
  const inventoryUrl = `/api/inventory?${queryParams.toString()}`;

  const { data, isLoading } = useQuery<InventoryListResult>({
    queryKey: [inventoryUrl],
  });

  const handleSearch = () => {
    setSearch(searchInput);
    setPage(0);
  };

  const handleRefresh = () => {
    queryClient.invalidateQueries({ queryKey: ["/api/inventory"] });
    queryClient.invalidateQueries({ queryKey: ["/api/inventory/stats"] });
  };

  const totalPages = data ? Math.ceil(data.total / limit) : 0;

  const warehouseColors = ["hsl(0, 70%, 50%)", "hsl(30, 70%, 50%)", "hsl(200, 70%, 50%)"];

  return (
    <div className="h-full overflow-auto p-6" data-testid="page-inventory">
      <div className="flex items-center gap-3 mb-6 flex-wrap">
        <div className="flex items-center justify-center w-10 h-10 rounded-md bg-red-500/15">
          <Boxes className="w-5 h-5 text-red-600" />
        </div>
        <div>
          <h1 className="text-xl font-semibold" data-testid="text-inventory-title">Inventory</h1>
          <p className="text-sm text-muted-foreground">Stock levels across warehouses</p>
        </div>
        <div className="ml-auto">
          <Button size="icon" variant="ghost" onClick={handleRefresh} data-testid="button-refresh-inventory">
            <RefreshCw className="w-4 h-4" />
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        {statsLoading ? (
          Array.from({ length: 4 }).map((_, i) => (
            <Card key={i}><CardContent className="p-4"><Skeleton className="h-12 w-full" /></CardContent></Card>
          ))
        ) : (
          <>
            <Card data-testid="card-total-skus">
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
                  <div className="flex items-center justify-center w-9 h-9 rounded-md bg-blue-500/15">
                    <Hash className="w-4 h-4 text-blue-600 dark:text-blue-400" />
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground">Unique SKUs</p>
                    <p className="text-lg font-bold">{stats?.totalSkus.toLocaleString() ?? 0}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
            <Card data-testid="card-total-units">
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
                  <div className="flex items-center justify-center w-9 h-9 rounded-md bg-emerald-500/15">
                    <Package className="w-4 h-4 text-emerald-600 dark:text-emerald-400" />
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground">Total Units</p>
                    <p className="text-lg font-bold">{stats?.totalUnits.toLocaleString() ?? 0}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
            <Card data-testid="card-low-stock">
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
                  <div className="flex items-center justify-center w-9 h-9 rounded-md bg-amber-500/15">
                    <AlertTriangle className="w-4 h-4 text-amber-600 dark:text-amber-400" />
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground">Low Stock</p>
                    <p className="text-lg font-bold">{stats?.lowStockCount.toLocaleString() ?? 0}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
            <Card data-testid="card-out-of-stock">
              <CardContent className="p-4">
                <div className="flex items-center gap-3">
                  <div className="flex items-center justify-center w-9 h-9 rounded-md bg-red-500/15">
                    <AlertTriangle className="w-4 h-4 text-red-600 dark:text-red-400" />
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground">Out of Stock</p>
                    <p className="text-lg font-bold">{stats?.outOfStockCount.toLocaleString() ?? 0}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </>
        )}
      </div>

      {stats && stats.byWarehouse.length > 0 && (
        <Card className="mb-6" data-testid="card-warehouse-breakdown">
          <CardHeader className="flex flex-row items-center gap-2 pb-2">
            <BarChart3 className="w-4 h-4 text-muted-foreground" />
            <CardTitle className="text-sm">Units by Warehouse</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-[180px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={stats.byWarehouse} layout="vertical" margin={{ left: 10, right: 20 }}>
                  <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                  <XAxis type="number" tickFormatter={(v) => v >= 1000 ? `${(v / 1000).toFixed(0)}K` : String(v)} />
                  <YAxis type="category" dataKey="warehouse" width={90} tick={{ fontSize: 12 }} />
                  <Tooltip formatter={(v: number) => [v.toLocaleString() + " units", "Stock"]} />
                  <Bar dataKey="units" radius={[0, 4, 4, 0]}>
                    {stats.byWarehouse.map((_, i) => (
                      <Cell key={i} fill={warehouseColors[i % warehouseColors.length]} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </CardContent>
        </Card>
      )}

      <Card data-testid="card-inventory-table">
        <CardHeader className="flex flex-row items-center justify-between gap-2 pb-2 flex-wrap">
          <CardTitle className="text-sm">Inventory Items</CardTitle>
          <Badge variant="outline">{data?.total.toLocaleString() ?? 0} items</Badge>
        </CardHeader>
        <CardContent className="p-0">
          <div className="flex items-center gap-2 p-4 border-b flex-wrap">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search by SKU or product name..."
                className="pl-9"
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSearch()}
                data-testid="input-search-inventory"
              />
            </div>
            <Select value={warehouse} onValueChange={(v) => { setWarehouse(v === "all" ? "" : v); setPage(0); }}>
              <SelectTrigger className="w-[160px]" data-testid="select-warehouse">
                <SelectValue placeholder="All Warehouses" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Warehouses</SelectItem>
                {stats?.byWarehouse.map((w) => (
                  <SelectItem key={w.warehouse} value={w.warehouse}>{w.warehouse}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select value={stockLevel} onValueChange={(v) => { setStockLevel(v === "all" ? "" : v); setPage(0); }}>
              <SelectTrigger className="w-[150px]" data-testid="select-stock-level">
                <SelectValue placeholder="All Levels" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Levels</SelectItem>
                <SelectItem value="healthy">In Stock (&gt;5)</SelectItem>
                <SelectItem value="low">Low Stock (1-5)</SelectItem>
                <SelectItem value="out">Out of Stock</SelectItem>
              </SelectContent>
            </Select>
            <Button variant="default" onClick={handleSearch} data-testid="button-search-inventory">
              Search
            </Button>
          </div>

          {isLoading ? (
            <div className="p-4 space-y-2">
              {Array.from({ length: 8 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full" />
              ))}
            </div>
          ) : (
            <>
              <div className="overflow-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead className="text-xs">SKU</TableHead>
                      <TableHead className="text-xs">Product</TableHead>
                      <TableHead className="text-xs">Warehouse</TableHead>
                      <TableHead className="text-xs">Vendor</TableHead>
                      <TableHead className="text-xs text-right">Available</TableHead>
                      <TableHead className="text-xs text-right">Price</TableHead>
                      <TableHead className="text-xs">Status</TableHead>
                      <TableHead className="text-xs">Updated</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {data?.rows.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={8} className="text-center py-8 text-muted-foreground">
                          No inventory items found
                        </TableCell>
                      </TableRow>
                    ) : (
                      data?.rows.map((item, idx) => (
                        <TableRow
                          key={`${item.sku}-${item.warehouse}-${idx}`}
                          className="cursor-pointer"
                          onClick={() => setSelectedItem(item)}
                          data-testid={`row-inventory-${item.sku}-${item.warehouse}`}
                        >
                          <TableCell className="font-mono text-xs font-medium">{item.sku}</TableCell>
                          <TableCell className="text-xs max-w-[200px] truncate">{item.productName || "-"}</TableCell>
                          <TableCell className="text-xs">{item.warehouse}</TableCell>
                          <TableCell className="text-xs text-muted-foreground">{item.vendor || "-"}</TableCell>
                          <TableCell className="text-right font-medium text-sm">{item.available.toLocaleString()}</TableCell>
                          <TableCell className="text-right text-xs text-muted-foreground">
                            {item.basePrice != null ? `$${item.basePrice.toFixed(2)}` : "-"}
                          </TableCell>
                          <TableCell><StockBadge available={item.available} /></TableCell>
                          <TableCell className="text-xs text-muted-foreground">
                            {new Date(item.updatedAt).toLocaleDateString("en-US", { month: "short", day: "numeric" })}
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </div>

              {totalPages > 1 && (
                <div className="flex items-center justify-between gap-2 p-4 border-t flex-wrap">
                  <p className="text-xs text-muted-foreground">
                    Showing {page * limit + 1}-{Math.min((page + 1) * limit, data?.total ?? 0)} of {data?.total.toLocaleString()}
                  </p>
                  <div className="flex items-center gap-1">
                    <Button
                      size="icon"
                      variant="outline"
                      disabled={page === 0}
                      onClick={() => setPage(page - 1)}
                      data-testid="button-prev-page"
                    >
                      <ChevronLeft className="w-4 h-4" />
                    </Button>
                    <span className="text-xs px-2">
                      {page + 1} / {totalPages}
                    </span>
                    <Button
                      size="icon"
                      variant="outline"
                      disabled={page >= totalPages - 1}
                      onClick={() => setPage(page + 1)}
                      data-testid="button-next-page"
                    >
                      <ChevronRight className="w-4 h-4" />
                    </Button>
                  </div>
                </div>
              )}
            </>
          )}
        </CardContent>
      </Card>

      <Sheet open={!!selectedItem} onOpenChange={(open) => !open && setSelectedItem(null)}>
        <SheetContent className="overflow-y-auto" data-testid="sheet-inventory-detail">
          {selectedItem && (
            <>
              <SheetHeader>
                <SheetTitle className="flex items-center gap-2">
                  <Boxes className="w-5 h-5" />
                  {selectedItem.sku}
                </SheetTitle>
              </SheetHeader>
              <div className="mt-4 space-y-1">
                {selectedItem.productName && (
                  <p className="text-sm font-medium mb-3">{selectedItem.productName}</p>
                )}
                <div className="mb-3">
                  <StockBadge available={selectedItem.available} />
                </div>
                <Separator className="my-3" />
                <DetailRow icon={Hash} label="SKU" value={selectedItem.sku} testId="detail-sku" />
                <DetailRow icon={Package} label="Available Units" value={selectedItem.available.toLocaleString()} testId="detail-available" />
                <DetailRow icon={Warehouse} label="Warehouse" value={selectedItem.warehouse} testId="detail-warehouse" />
                <DetailRow icon={Building2} label="Vendor" value={selectedItem.vendor} testId="detail-vendor" />
                <DetailRow icon={DollarSign} label="Base Price" value={selectedItem.basePrice != null ? `$${selectedItem.basePrice.toFixed(2)}` : null} testId="detail-price" />
                {selectedItem.basePrice != null && (
                  <DetailRow icon={DollarSign} label="Total Value" value={`$${(selectedItem.available * selectedItem.basePrice).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`} testId="detail-total-value" />
                )}
                <Separator className="my-3" />
                <DetailRow icon={Calendar} label="Created" value={formatDate(selectedItem.createdAt)} testId="detail-created" />
                <DetailRow icon={Calendar} label="Last Updated" value={formatDate(selectedItem.updatedAt)} testId="detail-updated" />
              </div>
            </>
          )}
        </SheetContent>
      </Sheet>
    </div>
  );
}

client/src/pages/odoo-products.tsx.content:
import { useState, useEffect, useCallback } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Search, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, Package } from "lucide-react";

interface OdooProduct {
  id: number;
  name: string;
  default_code: string | false;
  description: string | false;
  list_price: number;
  standard_price: number;
  type: string;
  categ_id: [number, string] | false;
  active: boolean;
  create_date: string;
  write_date: string;
}

function useDebounce(value: string, delay: number) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

export default function OdooProducts() {
  const [search, setSearch] = useState("");
  const debouncedSearch = useDebounce(search, 400);
  const [activeFilter, setActiveFilter] = useState("all");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [jumpInput, setJumpInput] = useState("");

  useEffect(() => { setPage(1); }, [debouncedSearch, activeFilter, pageSize]);

  const offset = (page - 1) * pageSize;

  const queryParams = new URLSearchParams();
  queryParams.set("limit", String(pageSize));
  queryParams.set("offset", String(offset));
  if (debouncedSearch) queryParams.set("search", debouncedSearch);
  if (activeFilter !== "all") queryParams.set("active", activeFilter);

  const { data, isLoading, error, isFetching } = useQuery<{ records: OdooProduct[]; total: number }>({
    queryKey: ["/api/odoo/products", debouncedSearch, activeFilter, offset, pageSize],
    queryFn: async () => {
      const res = await fetch(`/api/odoo/products?${queryParams.toString()}`);
      if (!res.ok) throw new Error("Failed to fetch Odoo products");
      return res.json();
    },
    placeholderData: (prev) => prev,
  });

  const totalPages = data ? Math.ceil(data.total / pageSize) : 0;

  const handleJump = useCallback(() => {
    const p = parseInt(jumpInput);
    if (p >= 1 && p <= totalPages) { setPage(p); setJumpInput(""); }
  }, [jumpInput, totalPages]);

  return (
    <div className="h-full overflow-auto p-4 space-y-4">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-2">
          <Package className="w-5 h-5" />
          <h1 className="text-xl font-semibold" data-testid="text-page-title">Odoo Products</h1>
          {data && (
            <Badge variant="secondary" data-testid="badge-total-count">
              {data.total.toLocaleString()} total
            </Badge>
          )}
          {isFetching && !isLoading && (
            <span className="text-xs text-muted-foreground">Loading...</span>
          )}
        </div>
      </div>

      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2 flex-wrap">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search by name, SKU, or description..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-9"
                data-testid="input-search"
              />
            </div>
            <Select value={activeFilter} onValueChange={setActiveFilter}>
              <SelectTrigger className="w-[140px]" data-testid="select-active-filter">
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All</SelectItem>
                <SelectItem value="true">Active</SelectItem>
                <SelectItem value="false">Archived</SelectItem>
              </SelectContent>
            </Select>
            <Select value={String(pageSize)} onValueChange={(v) => setPageSize(Number(v))}>
              <SelectTrigger className="w-[100px]" data-testid="select-page-size">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="10">10 / page</SelectItem>
                <SelectItem value="25">25 / page</SelectItem>
                <SelectItem value="50">50 / page</SelectItem>
                <SelectItem value="100">100 / page</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardHeader>
        <CardContent className="p-0">
          {isLoading ? (
            <div className="p-4 space-y-2">
              {Array.from({ length: 8 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full" />
              ))}
            </div>
          ) : error ? (
            <div className="p-6 text-center text-destructive" data-testid="text-error">
              Failed to load products from Odoo. Please check the connection.
            </div>
          ) : !data?.records.length ? (
            <div className="p-6 text-center text-muted-foreground" data-testid="text-empty">
              No products found.
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>SKU</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Category</TableHead>
                    <TableHead className="text-right">Sale Price</TableHead>
                    <TableHead className="text-right">Cost</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {data.records.map((p) => (
                    <TableRow key={p.id} data-testid={`row-product-${p.id}`}>
                      <TableCell className="font-mono text-xs">
                        {p.default_code || "-"}
                      </TableCell>
                      <TableCell className="font-medium max-w-[250px] truncate">
                        {p.name}
                      </TableCell>
                      <TableCell className="text-muted-foreground text-sm">
                        {Array.isArray(p.categ_id) ? p.categ_id[1] : "-"}
                      </TableCell>
                      <TableCell className="text-right font-mono">
                        ${p.list_price.toFixed(2)}
                      </TableCell>
                      <TableCell className="text-right font-mono">
                        ${p.standard_price.toFixed(2)}
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline" className="text-xs capitalize">
                          {p.type === "consu" ? "consumable" : p.type === "service" ? "service" : p.type}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <Badge variant={p.active ? "default" : "secondary"}>
                          {p.active ? "Active" : "Archived"}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}

          {data && data.total > 0 && (
            <div className="flex items-center justify-between gap-2 p-3 border-t flex-wrap">
              <span className="text-sm text-muted-foreground" data-testid="text-page-info">
                {offset + 1}-{Math.min(offset + pageSize, data.total)} of {data.total.toLocaleString()}
              </span>
              <div className="flex items-center gap-1">
                <Button variant="outline" size="icon" disabled={page <= 1}
                  onClick={() => setPage(1)} data-testid="button-first-page">
                  <ChevronsLeft className="w-4 h-4" />
                </Button>
                <Button variant="outline" size="icon" disabled={page <= 1}
                  onClick={() => setPage(page - 1)} data-testid="button-prev-page">
                  <ChevronLeft className="w-4 h-4" />
                </Button>
                <div className="flex items-center gap-1 px-1">
                  <Input
                    className="w-14 text-center"
                    value={jumpInput || String(page)}
                    onChange={(e) => setJumpInput(e.target.value)}
                    onBlur={handleJump}
                    onKeyDown={(e) => e.key === "Enter" && handleJump()}
                    data-testid="input-page-jump"
                  />
                  <span className="text-sm text-muted-foreground">/ {totalPages}</span>
                </div>
                <Button variant="outline" size="icon" disabled={page >= totalPages}
                  onClick={() => setPage(page + 1)} data-testid="button-next-page">
                  <ChevronRight className="w-4 h-4" />
                </Button>
                <Button variant="outline" size="icon" disabled={page >= totalPages}
                  onClick={() => setPage(totalPages)} data-testid="button-last-page">
                  <ChevronsRight className="w-4 h-4" />
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/sales-flow.tsx.content:
import { useState, useEffect, useCallback } from "react";
import { useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from "@/components/ui/command";
import {
  Search, ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight,
  Users, ShoppingCart, FileText, Building2, ArrowLeft, ChevronRightIcon,
  DollarSign, Package, Receipt, TrendingUp, ChevronDown, ChevronUp, Filter,
} from "lucide-react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, ResponsiveContainer, Tooltip, Cell } from "recharts";

interface OdooPartner {
  id: number;
  name: string;
  email: string | false;
  phone: string | false;
  mobile: string | false;
  city: string | false;
  state_id: [number, string] | false;
  country_id: [number, string] | false;
  is_company: boolean;
  customer_rank: number;
  supplier_rank: number;
  active: boolean;
  parent_id: [number, string] | false;
  child_ids: number[];
}

interface OdooSaleOrder {
  id: number;
  name: string;
  partner_id: [number, string] | false;
  date_order: string;
  state: string;
  amount_total: number;
  amount_untaxed: number;
  amount_tax: number;
  order_line: number[];
  currency_id: [number, string] | false;
  create_date: string;
  write_date: string;
}

interface OdooInvoice {
  id: number;
  name: string;
  partner_id: [number, string] | false;
  invoice_date: string | false;
  invoice_date_due: string | false;
  state: string;
  payment_state: string;
  amount_total: number;
  amount_residual: number;
  amount_untaxed: number;
  amount_tax: number;
  currency_id: [number, string] | false;
  invoice_origin: string | false;
  ref: string | false;
  create_date: string;
  write_date: string;
}

const orderStateLabels: Record<string, string> = {
  draft: "Quotation",
  sent: "Quotation Sent",
  sale: "Sales Order",
  done: "Locked",
  cancel: "Cancelled",
};

const orderStateVariants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  draft: "outline",
  sent: "secondary",
  sale: "default",
  done: "secondary",
  cancel: "destructive",
};

const invoiceStateLabels: Record<string, string> = {
  draft: "Draft",
  posted: "Posted",
  cancel: "Cancelled",
};

const invoiceStateVariants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  draft: "outline",
  posted: "default",
  cancel: "destructive",
};

const paymentLabels: Record<string, string> = {
  not_paid: "Not Paid",
  partial: "Partial",
  paid: "Paid",
  in_payment: "In Payment",
  reversed: "Reversed",
};

const paymentVariants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  not_paid: "destructive",
  partial: "secondary",
  paid: "default",
  in_payment: "secondary",
  reversed: "outline",
};

function useDebounce(value: string, delay: number) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

function Pagination({ page, totalPages, pageSize, total, offset, setPage, jumpInput, setJumpInput, handleJump }: {
  page: number; totalPages: number; pageSize: number; total: number; offset: number;
  setPage: (p: number) => void; jumpInput: string; setJumpInput: (v: string) => void; handleJump: () => void;
}) {
  if (total <= 0) return null;
  return (
    <div className="flex items-center justify-between gap-2 p-3 border-t flex-wrap">
      <span className="text-sm text-muted-foreground" data-testid="text-page-info">
        {offset + 1}-{Math.min(offset + pageSize, total)} of {total.toLocaleString()}
      </span>
      <div className="flex items-center gap-1">
        <Button variant="outline" size="icon" disabled={page <= 1}
          onClick={() => setPage(1)} data-testid="button-first-page">
          <ChevronsLeft className="w-4 h-4" />
        </Button>
        <Button variant="outline" size="icon" disabled={page <= 1}
          onClick={() => setPage(page - 1)} data-testid="button-prev-page">
          <ChevronLeft className="w-4 h-4" />
        </Button>
        <div className="flex items-center gap-1 px-1">
          <Input
            className="w-14 text-center"
            value={jumpInput || String(page)}
            onChange={(e) => setJumpInput(e.target.value)}
            onBlur={handleJump}
            onKeyDown={(e) => e.key === "Enter" && handleJump()}
            data-testid="input-page-jump"
          />
          <span className="text-sm text-muted-foreground">/ {totalPages}</span>
        </div>
        <Button variant="outline" size="icon" disabled={page >= totalPages}
          onClick={() => setPage(page + 1)} data-testid="button-next-page">
          <ChevronRight className="w-4 h-4" />
        </Button>
        <Button variant="outline" size="icon" disabled={page >= totalPages}
          onClick={() => setPage(totalPages)} data-testid="button-last-page">
          <ChevronsRight className="w-4 h-4" />
        </Button>
      </div>
    </div>
  );
}

function PageSizeSelector({ pageSize, setPageSize }: { pageSize: number; setPageSize: (v: number) => void }) {
  return (
    <Select value={String(pageSize)} onValueChange={(v) => setPageSize(Number(v))}>
      <SelectTrigger className="w-[100px]" data-testid="select-page-size">
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value="10">10 / page</SelectItem>
        <SelectItem value="25">25 / page</SelectItem>
        <SelectItem value="50">50 / page</SelectItem>
        <SelectItem value="100">100 / page</SelectItem>
      </SelectContent>
    </Select>
  );
}

function LoadingSkeleton() {
  return (
    <div className="p-4 space-y-2">
      {Array.from({ length: 8 }).map((_, i) => (
        <Skeleton key={i} className="h-10 w-full" />
      ))}
    </div>
  );
}

export function CustomersTab() {
  const [, navigate] = useLocation();
  const [search, setSearch] = useState("");
  const debouncedSearch = useDebounce(search, 400);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [jumpInput, setJumpInput] = useState("");

  useEffect(() => { setPage(1); }, [debouncedSearch, pageSize]);

  const offset = (page - 1) * pageSize;
  const queryParams = new URLSearchParams();
  queryParams.set("limit", String(pageSize));
  queryParams.set("offset", String(offset));
  queryParams.set("type", "customer");
  queryParams.set("parentOnly", "true");
  if (debouncedSearch) queryParams.set("search", debouncedSearch);

  const { data, isLoading, error, isFetching } = useQuery<{ records: OdooPartner[]; total: number }>({
    queryKey: ["/api/odoo/partners", "customer", "parentOnly", debouncedSearch, offset, pageSize],
    queryFn: async () => {
      const res = await fetch(`/api/odoo/partners?${queryParams.toString()}`);
      if (!res.ok) throw new Error("Failed to fetch customers");
      return res.json();
    },
    placeholderData: (prev) => prev,
  });

  const totalPages = data ? Math.ceil(data.total / pageSize) : 0;
  const handleJump = useCallback(() => {
    const p = parseInt(jumpInput);
    if (p >= 1 && p <= totalPages) { setPage(p); setJumpInput(""); }
  }, [jumpInput, totalPages]);

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between gap-2 flex-wrap">
          <div className="flex items-center gap-2">
            {data && <Badge variant="secondary" data-testid="badge-customers-count">{data.total.toLocaleString()} parent accounts</Badge>}
            {isFetching && !isLoading && <span className="text-xs text-muted-foreground">Loading...</span>}
          </div>
        </div>
        <div className="flex items-center gap-2 flex-wrap mt-2">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input placeholder="Search by name, email, or phone..." value={search}
              onChange={(e) => setSearch(e.target.value)} className="pl-9" data-testid="input-search-customers" />
          </div>
          <PageSizeSelector pageSize={pageSize} setPageSize={setPageSize} />
        </div>
      </CardHeader>
      <CardContent className="p-0">
        {isLoading ? <LoadingSkeleton /> : error ? (
          <div className="p-6 text-center text-destructive">Failed to load customers.</div>
        ) : !data?.records.length ? (
          <div className="p-6 text-center text-muted-foreground">No customers found.</div>
        ) : (
          <div className="overflow-x-auto">
            <Table className="table-fixed w-full">
              <TableHeader>
                <TableRow>
                  <TableHead className="w-[18%]">Name</TableHead>
                  <TableHead className="w-[20%]">Email</TableHead>
                  <TableHead className="w-[13%]">Phone</TableHead>
                  <TableHead className="w-[11%]">City</TableHead>
                  <TableHead className="w-[12%]">State</TableHead>
                  <TableHead className="w-[12%]">Country</TableHead>
                  <TableHead className="w-[14%]">Sub-accounts</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {data.records.map((p) => {
                  const hasChildren = Array.isArray(p.child_ids) && p.child_ids.length > 0;
                  return (
                    <TableRow
                      key={p.id}
                      data-testid={`row-customer-${p.id}`}
                      className={hasChildren ? "cursor-pointer hover-elevate" : ""}
                      onClick={() => hasChildren && navigate(`/sales-flow/customers/${p.id}`)}
                    >
                      <TableCell className="font-medium">
                        <div className="flex items-center gap-2">
                          <Building2 className="w-4 h-4 text-muted-foreground shrink-0" />
                          <span className="truncate">{p.name}</span>
                          {p.is_company && <Badge variant="outline" className="text-xs shrink-0">Company</Badge>}
                          {hasChildren && <ChevronRightIcon className="w-4 h-4 text-muted-foreground ml-auto shrink-0" />}
                        </div>
                      </TableCell>
                      <TableCell className="text-sm truncate" title={p.email || ""}>{p.email || "-"}</TableCell>
                      <TableCell className="text-sm truncate">{p.phone || p.mobile || "-"}</TableCell>
                      <TableCell className="text-sm truncate">{p.city || "-"}</TableCell>
                      <TableCell className="text-sm truncate">{Array.isArray(p.state_id) ? p.state_id[1] : "-"}</TableCell>
                      <TableCell className="text-sm truncate">{Array.isArray(p.country_id) ? p.country_id[1] : "-"}</TableCell>
                      <TableCell>
                        {hasChildren ? (
                          <Badge variant="secondary">{p.child_ids.length}</Badge>
                        ) : (
                          <span className="text-sm text-muted-foreground">-</span>
                        )}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        )}
        {data && <Pagination page={page} totalPages={totalPages} pageSize={pageSize} total={data.total}
          offset={offset} setPage={setPage} jumpInput={jumpInput} setJumpInput={setJumpInput} handleJump={handleJump} />}
      </CardContent>
    </Card>
  );
}

interface DashboardData {
  kpis: {
    totalRevenue: number;
    totalOrders: number;
    avgOrderValue: number;
    openInvoiceCount: number;
    openInvoiceTotal: number;
  };
  invoiceBreakdown: {
    paid: number;
    unpaid: number;
    overdue: number;
    totalInvoices: number;
  };
  recentOrders: {
    id: number;
    name: string;
    partner_name: string;
    date_order: string;
    state: string;
    amount_total: number;
    has_invoice: boolean;
  }[];
  topProducts: {
    id: number;
    name: string;
    totalQty: number;
    totalRevenue: number;
  }[];
  childCount: number;
}

const CHART_COLORS = [
  "hsl(var(--chart-1))",
  "hsl(var(--chart-2))",
  "hsl(var(--chart-3))",
  "hsl(var(--chart-4))",
  "hsl(var(--chart-5))",
  "hsl(220 70% 55%)",
  "hsl(280 65% 55%)",
  "hsl(340 65% 55%)",
  "hsl(30 80% 55%)",
  "hsl(160 60% 45%)",
];

function formatCurrency(val: number) {
  return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(val);
}

function formatNumber(val: number) {
  return new Intl.NumberFormat("en-US").format(val);
}

export function CustomerDetailPage({ customerId }: { customerId: number }) {
  const [, navigate] = useLocation();
  const [search, setSearch] = useState("");
  const debouncedSearch = useDebounce(search, 400);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [jumpInput, setJumpInput] = useState("");
  const [showAllOrders, setShowAllOrders] = useState(false);
  const [showAllProducts, setShowAllProducts] = useState(false);
  const [selectedSubAccount, setSelectedSubAccount] = useState<string>("all");
  const [subAccountOpen, setSubAccountOpen] = useState(false);

  useEffect(() => { setPage(1); }, [debouncedSearch, pageSize]);
  useEffect(() => { setShowAllOrders(false); setShowAllProducts(false); }, [selectedSubAccount]);

  const { data: parent, isLoading: parentLoading } = useQuery<OdooPartner>({
    queryKey: ["/api/odoo/partners", customerId],
    queryFn: async () => {
      const res = await fetch(`/api/odoo/partners/${customerId}`);
      if (!res.ok) throw new Error("Failed to fetch customer");
      return res.json();
    },
  });

  const { data: allChildren } = useQuery<{ records: { id: number; name: string }[]; total: number }>({
    queryKey: ["/api/odoo/partners", "allChildren", customerId],
    queryFn: async () => {
      const params = new URLSearchParams();
      params.set("limit", "10000");
      params.set("offset", "0");
      params.set("parentId", String(customerId));
      params.set("type", "customer");
      const res = await fetch(`/api/odoo/partners?${params.toString()}`);
      if (!res.ok) throw new Error("Failed to fetch children");
      return res.json();
    },
  });

  const dashboardPartnerId = selectedSubAccount === "all" ? customerId : parseInt(selectedSubAccount);

  const { data: dashboard, isLoading: dashboardLoading, error: dashboardError } = useQuery<DashboardData>({
    queryKey: ["/api/odoo/partners", dashboardPartnerId, "dashboard"],
    queryFn: async () => {
      const res = await fetch(`/api/odoo/partners/${dashboardPartnerId}/dashboard`);
      if (!res.ok) throw new Error("Failed to fetch dashboard");
      return res.json();
    },
  });

  const offset = (page - 1) * pageSize;
  const queryParams = new URLSearchParams();
  queryParams.set("limit", String(pageSize));
  queryParams.set("offset", String(offset));
  queryParams.set("parentId", String(customerId));
  queryParams.set("type", "customer");
  if (debouncedSearch) queryParams.set("search", debouncedSearch);

  const { data: childrenData, isLoading: childrenLoading, error, isFetching } = useQuery<{ records: OdooPartner[]; total: number }>({
    queryKey: ["/api/odoo/partners", "children", customerId, debouncedSearch, offset, pageSize],
    queryFn: async () => {
      const res = await fetch(`/api/odoo/partners?${queryParams.toString()}`);
      if (!res.ok) throw new Error("Failed to fetch child companies");
      return res.json();
    },
    placeholderData: (prev) => prev,
  });

  const totalPages = childrenData ? Math.ceil(childrenData.total / pageSize) : 0;
  const handleJump = useCallback(() => {
    const p = parseInt(jumpInput);
    if (p >= 1 && p <= totalPages) { setPage(p); setJumpInput(""); }
  }, [jumpInput, totalPages]);

  const invoiceChartData = dashboard ? [
    { name: "Paid", value: dashboard.invoiceBreakdown.paid },
    { name: "Unpaid", value: dashboard.invoiceBreakdown.unpaid },
  ].filter(d => d.value > 0) : [];

  return (
    <div className="h-full overflow-auto p-4 space-y-4">
      <div className="flex items-center gap-2 flex-wrap">
        <Button
          variant="ghost"
          size="icon"
