import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  AlertTriangle,
  Search,
  RefreshCw,
  Hash,
  Calendar,
  ChevronLeft,
  ChevronRight,
  FileText,
  Radio,
  Navigation,
  MessageSquare,
  Tag,
  Building2,
  Copy,
  Check,
} from "lucide-react";
import { queryClient } from "@/lib/queryClient";
import { useState } from "react";
import type { ErrorRow, ErrorListResult, ErrorStats } from "@shared/schema";

function formatDate(dateStr: string | null): string {
  if (!dateStr) return "-";
  const d = new Date(dateStr);
  return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

function formatDateTime(dateStr: string | null): string {
  if (!dateStr) return "-";
  const d = new Date(dateStr);
  return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
}

function DetailRow({ icon: Icon, label, value, testId }: { icon: any; label: string; value: string | null | undefined; testId?: string }) {
  return (
    <div className="flex items-start gap-3 py-2.5">
      <div className="flex items-center justify-center w-8 h-8 rounded-md bg-muted shrink-0 mt-0.5">
        <Icon className="w-3.5 h-3.5 text-muted-foreground" />
      </div>
      <div className="min-w-0 flex-1">
        <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-medium">{label}</p>
        <p className="text-sm mt-0.5 break-words" data-testid={testId}>{value || "-"}</p>
      </div>
    </div>
  );
}

function CopyableContent({ label, content, icon: Icon }: { label: string; content: string | null; icon: any }) {
  const [copied, setCopied] = useState(false);

  if (!content) return <DetailRow icon={Icon} label={label} value="-" />;

  const handleCopy = () => {
    navigator.clipboard.writeText(content);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  let displayContent = content;
  try {
    const parsed = JSON.parse(content);
    displayContent = JSON.stringify(parsed, null, 2);
  } catch {
    displayContent = content;
  }

  return (
    <div className="py-2.5">
      <div className="flex items-center justify-between gap-2 mb-1">
        <div className="flex items-center gap-2">
          <div className="flex items-center justify-center w-8 h-8 rounded-md bg-muted shrink-0">
            <Icon className="w-3.5 h-3.5 text-muted-foreground" />
          </div>
          <p className="text-[11px] text-muted-foreground uppercase tracking-wider font-medium">{label}</p>
        </div>
        <Button size="icon" variant="ghost" onClick={handleCopy} data-testid={`button-copy-${label.toLowerCase().replace(/\s+/g, '-')}`}>
          {copied ? <Check className="w-3.5 h-3.5 text-emerald-500" /> : <Copy className="w-3.5 h-3.5" />}
        </Button>
      </div>
      <pre className="text-xs bg-muted/50 border rounded-md p-3 overflow-auto max-h-[300px] whitespace-pre-wrap break-words font-mono">
        {displayContent}
      </pre>
    </div>
  );
}

function ErrorDetailSheet({ error, open, onClose }: { error: ErrorRow | null; open: boolean; onClose: () => void }) {
  if (!error) return null;

  return (
    <Sheet open={open} onOpenChange={(o) => !o && onClose()}>
      <SheetContent className="overflow-y-auto sm:max-w-lg" data-testid="sheet-error-detail">
        <SheetHeader className="pb-4">
          <div className="flex items-center gap-3">
            <div className="flex items-center justify-center w-14 h-14 rounded-md bg-red-500/15">
              <AlertTriangle className="w-6 h-6 text-red-600 dark:text-red-400" />
            </div>
            <div className="min-w-0 flex-1">
              <SheetTitle className="text-lg truncate" data-testid="text-detail-error-id">{error.id}</SheetTitle>
              <p className="text-xs text-muted-foreground">{formatDateTime(error.date)}</p>
            </div>
          </div>
        </SheetHeader>

        <Separator />

        <div className="py-2">
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider pb-1 pt-2">Error Info</p>
          <DetailRow icon={Hash} label="ID" value={error.id} testId="text-detail-id" />
          <DetailRow icon={Hash} label="Internal ID" value={String(error._id)} testId="text-detail-internal-id" />
          <DetailRow icon={Tag} label="Type" value={error.type} testId="text-detail-type" />
          <DetailRow icon={Radio} label="Channel" value={error.channelName} testId="text-detail-channel" />
          <DetailRow icon={Navigation} label="Destination" value={error.destination} testId="text-detail-destination" />
          <DetailRow icon={Building2} label="Vendor" value={error.vendor} testId="text-detail-vendor" />
          <DetailRow icon={Calendar} label="Date" value={formatDateTime(error.date)} testId="text-detail-date" />
        </div>

        <Separator />

        <div className="py-2">
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider pb-1 pt-2">Guide</p>
          <p className="text-sm text-muted-foreground break-words" data-testid="text-detail-guide">{error.guide || "-"}</p>
        </div>

        {error.statusMessage && (
          <>
            <Separator />
            <div className="py-2">
              <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider pb-1 pt-2">Status Message</p>
              <p className="text-sm break-words" data-testid="text-detail-status-message">{error.statusMessage}</p>
            </div>
          </>
        )}

        {error.detail && (
          <>
            <Separator />
            <CopyableContent label="Detail" content={error.detail} icon={FileText} />
          </>
        )}

        {error.message && (
          <>
            <Separator />
            <CopyableContent label="Message" content={error.message} icon={MessageSquare} />
          </>
        )}

        {error.response && (
          <>
            <Separator />
            <CopyableContent label="Response" content={error.response} icon={FileText} />
          </>
        )}

        <Separator />

        <div className="py-2">
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider pb-1 pt-2">Identifiers</p>
          <DetailRow icon={Hash} label="Message ID" value={error.messageId} testId="text-detail-message-id" />
          <DetailRow icon={Hash} label="Channel ID" value={error.channelId} testId="text-detail-channel-id" />
          <DetailRow icon={Hash} label="Destination ID" value={error.destinationId} testId="text-detail-destination-id" />
        </div>
      </SheetContent>
    </Sheet>
  );
}

function getTypeBadgeStyle(type: string | null) {
  switch (type) {
    case "EDI":
      return "bg-blue-500/15 text-blue-700 dark:text-blue-400 border-blue-200 dark:border-blue-800";
    case "JSON":
      return "bg-amber-500/15 text-amber-700 dark:text-amber-400 border-amber-200 dark:border-amber-800";
    case "XML":
      return "bg-violet-500/15 text-violet-700 dark:text-violet-400 border-violet-200 dark:border-violet-800";
    default:
      return "";
  }
}

export default function Errors() {
  const [page, setPage] = useState(0);
  const [search, setSearch] = useState("");
  const [searchInput, setSearchInput] = useState("");
  const [typeFilter, setTypeFilter] = useState("");
  const [channelFilter, setChannelFilter] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [selectedError, setSelectedError] = useState<ErrorRow | null>(null);
  const limit = 25;

  const { data: stats, isLoading: statsLoading } = useQuery<ErrorStats>({
    queryKey: ["/api/errors/stats"],
  });

  const queryParams = new URLSearchParams();
  queryParams.set("limit", String(limit));
  queryParams.set("offset", String(page * limit));
  if (search) queryParams.set("search", search);
  if (typeFilter) queryParams.set("type", typeFilter);
  if (channelFilter) queryParams.set("channelName", channelFilter);
  if (dateFrom) queryParams.set("dateFrom", dateFrom);
  if (dateTo) queryParams.set("dateTo", dateTo);

  const errorsUrl = `/api/errors?${queryParams.toString()}`;

  const { data: errors, isLoading: errorsLoading } = useQuery<ErrorListResult>({
    queryKey: [errorsUrl],
  });

  const handleSearch = () => {
    setSearch(searchInput);
    setPage(0);
  };

  const handleRefresh = () => {
    queryClient.invalidateQueries({ predicate: (query) => {
      const key = query.queryKey[0];
      return typeof key === "string" && key.startsWith("/api/errors");
    }});
  };

  const totalRows = errors?.total ?? 0;
  const totalPages = Math.ceil(totalRows / limit);

  return (
    <div className="flex flex-col h-full gap-4 p-4 overflow-auto" data-testid="page-errors">
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-3">
          <div className="flex items-center justify-center w-10 h-10 rounded-md bg-red-500/15">
            <AlertTriangle className="w-5 h-5 text-red-600 dark:text-red-400" />
          </div>
          <div>
            <h1 className="text-xl font-semibold" data-testid="text-errors-title">Errors</h1>
            <p className="text-sm text-muted-foreground">View and analyze error logs</p>
          </div>
        </div>
        <Button size="icon" variant="ghost" onClick={handleRefresh} data-testid="button-refresh-errors">
          <RefreshCw className="w-4 h-4" />
        </Button>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <Card data-testid="card-total-errors">
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <div className="flex items-center justify-center w-9 h-9 rounded-md bg-red-500/15">
                <AlertTriangle className="w-4 h-4 text-red-600 dark:text-red-400" />
              </div>
              <div>
                <p className="text-xs text-muted-foreground">Total Errors</p>
                {statsLoading ? (
                  <Skeleton className="h-6 w-16 mt-0.5" />
                ) : (
                  <p className="text-lg font-bold" data-testid="text-total-errors">{stats?.total.toLocaleString()}</p>
                )}
              </div>
            </div>
          </CardContent>
        </Card>

        {stats?.byType.slice(0, 3).map((t) => (
          <Card key={t.type} data-testid={`card-type-${t.type}`}>
            <CardContent className="p-4">
              <div className="flex items-center gap-3">
                <div className="flex items-center justify-center w-9 h-9 rounded-md bg-muted">
                  <Tag className="w-4 h-4 text-muted-foreground" />
                </div>
                <div>
                  <p className="text-xs text-muted-foreground">{t.type}</p>
                  {statsLoading ? (
                    <Skeleton className="h-6 w-16 mt-0.5" />
                  ) : (
                    <p className="text-lg font-bold">{t.cnt.toLocaleString()}</p>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card className="flex-1 flex flex-col min-h-0">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between gap-2 flex-wrap">
            <div className="flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 text-muted-foreground" />
              <CardTitle className="text-base">All Errors</CardTitle>
              <Badge variant="secondary" data-testid="badge-error-count">{totalRows.toLocaleString()}</Badge>
            </div>
            {totalPages > 1 && (
              <div className="flex items-center gap-1">
                <Button
                  size="icon"
                  variant="ghost"
                  disabled={page === 0}
                  onClick={() => setPage((p) => Math.max(0, p - 1))}
                  data-testid="button-prev-page"
                >
                  <ChevronLeft className="w-4 h-4" />
                </Button>
                <span className="text-xs text-muted-foreground px-2">
                  {page + 1} / {totalPages}
                </span>
                <Button
                  size="icon"
                  variant="ghost"
                  disabled={page >= totalPages - 1}
                  onClick={() => setPage((p) => p + 1)}
                  data-testid="button-next-page"
                >
                  <ChevronRight className="w-4 h-4" />
                </Button>
              </div>
            )}
          </div>
          <div className="flex items-center gap-2 pt-2 flex-wrap">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
              <Input
                placeholder="Search errors..."
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSearch()}
                className="pl-8"
                data-testid="input-search"
              />
            </div>
            <Select value={typeFilter} onValueChange={(v) => { setTypeFilter(v === "all" ? "" : v); setPage(0); }}>
              <SelectTrigger className="w-[120px]" data-testid="select-type-filter">
                <SelectValue placeholder="Type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Types</SelectItem>
                <SelectItem value="EDI">EDI</SelectItem>
                <SelectItem value="JSON">JSON</SelectItem>
                <SelectItem value="XML">XML</SelectItem>
              </SelectContent>
            </Select>
            <Select value={channelFilter} onValueChange={(v) => { setChannelFilter(v === "all" ? "" : v); setPage(0); }}>
              <SelectTrigger className="w-[200px]" data-testid="select-channel-filter">
                <SelectValue placeholder="Channel" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Channels</SelectItem>
                {stats?.byChannel.map((c) => (
                  <SelectItem key={c.channelName} value={c.channelName}>{c.channelName}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Input
              type="date"
              value={dateFrom}
              onChange={(e) => { setDateFrom(e.target.value); setPage(0); }}
              className="w-[140px]"
              data-testid="input-date-from"
            />
            <Input
              type="date"
              value={dateTo}
              onChange={(e) => { setDateTo(e.target.value); setPage(0); }}
              className="w-[140px]"
              data-testid="input-date-to"
            />
            <Button variant="outline" onClick={handleSearch} data-testid="button-search">
              <Search className="w-3.5 h-3.5 mr-1.5" />
              Search
            </Button>
          </div>
        </CardHeader>
        <CardContent className="flex-1 p-0 min-h-0 overflow-auto">
          {errorsLoading ? (
            <div className="p-4 space-y-3">
              {Array.from({ length: 8 }).map((_, i) => (
                <div key={i} className="flex items-center gap-3">
                  <div className="space-y-1.5 flex-1">
                    <Skeleton className="h-4 w-48" />
                    <Skeleton className="h-3 w-32" />
                  </div>
                </div>
              ))}
            </div>
          ) : errors && errors.rows.length > 0 ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-[100px]">ID</TableHead>
                  <TableHead className="w-[70px]">Type</TableHead>
                  <TableHead className="min-w-[150px]">Channel</TableHead>
                  <TableHead className="min-w-[150px]">Destination</TableHead>
                  <TableHead className="min-w-[250px]">Guide</TableHead>
                  <TableHead className="w-[100px]">Vendor</TableHead>
                  <TableHead className="w-[130px]">Date</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {errors.rows.map((row) => (
                  <TableRow
                    key={row._id}
                    className="cursor-pointer"
                    onClick={() => setSelectedError(row)}
                    data-testid={`row-error-${row._id}`}
                  >
                    <TableCell>
                      <span className="text-sm font-mono font-medium" data-testid={`text-id-${row._id}`}>
                        {row.id}
                      </span>
                    </TableCell>
                    <TableCell>
                      {row.type && (
                        <Badge
                          variant="outline"
                          className={`text-[10px] ${getTypeBadgeStyle(row.type)}`}
                          data-testid={`badge-type-${row._id}`}
                        >
                          {row.type}
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell>
                      <span className="text-sm truncate block max-w-[200px]" data-testid={`text-channel-${row._id}`}>
                        {row.channelName || "-"}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm truncate block max-w-[200px]" data-testid={`text-destination-${row._id}`}>
                        {row.destination || "-"}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm text-muted-foreground truncate block max-w-[350px]" data-testid={`text-guide-${row._id}`}>
                        {row.guide || "-"}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span className="text-sm" data-testid={`text-vendor-${row._id}`}>
                        {row.vendor || "-"}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span className="text-xs text-muted-foreground" data-testid={`text-date-${row._id}`}>
                        {formatDate(row.date)}
                      </span>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <AlertTriangle className="w-10 h-10 text-muted-foreground/40 mb-3" />
              <p className="text-sm font-medium text-muted-foreground">No errors found</p>
              <p className="text-xs text-muted-foreground/60 mt-1">
                {search || typeFilter || channelFilter ? "Try adjusting your filters" : "No error records available"}
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      <ErrorDetailSheet
        error={selectedError}
        open={!!selectedError}
        onClose={() => setSelectedError(null)}
      />
    </div>
  );
}

client/src/pages/odoo-bill-detail.tsx.content:
import { useQuery } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Separator } from "@/components/ui/separator";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  ArrowLeft, Receipt, Package, User, DollarSign,
  Calendar, Clock, AlertCircle, Mail, Phone,
  MapPin, Hash, CreditCard, CircleDot, CircleCheck, XCircle,
} from "lucide-react";

const stateLabels: Record<string, string> = {
  draft: "Draft", posted: "Posted", cancel: "Cancelled",
};
const stateVariants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  draft: "outline", posted: "default", cancel: "destructive",
};
const paymentLabels: Record<string, string> = {
  not_paid: "Not Paid", in_payment: "In Payment", paid: "Paid",
  partial: "Partial", reversed: "Reversed",
};
const paymentVariants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  not_paid: "destructive", in_payment: "secondary", paid: "default",
  partial: "outline", reversed: "destructive",
};

interface BillDetailData {
  bill: any;
  lines: any[];
  partner: any;
  sourcePO: { id: number; name: string } | null;
}

export default function OdooBillDetail({ billId }: { billId: number }) {
  const [, navigate] = useLocation();

  const { data, isLoading, error } = useQuery<BillDetailData>({
    queryKey: ["/api/odoo/bills", billId],
    enabled: !!billId,
  });

  if (isLoading) {
    return (
      <div className="h-full overflow-auto p-4 space-y-4" data-testid="page-odoo-bill-loading">
        <Skeleton className="h-10 w-48" />
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <Skeleton className="h-32" /><Skeleton className="h-32" /><Skeleton className="h-32" />
        </div>
        <Skeleton className="h-64" />
      </div>
    );
  }

  if (error || !data?.bill) {
    return (
      <div className="h-full overflow-auto p-4" data-testid="page-odoo-bill-error">
        <Button variant="ghost" onClick={() => navigate("/purchase-flow")} data-testid="button-back">
          <ArrowLeft className="w-4 h-4 mr-2" /> Back to POs & Bills
        </Button>
        <div className="flex items-center justify-center h-64">
          <div className="text-center space-y-2">
            <AlertCircle className="w-10 h-10 text-destructive mx-auto" />
            <p className="text-destructive font-medium">Failed to load bill</p>
          </div>
        </div>
      </div>
    );
  }

  const { bill, lines, partner, sourcePO } = data;
  const vendorName = Array.isArray(bill.partner_id) ? bill.partner_id[1] : "Unknown";
  const amountPaid = bill.amount_total - bill.amount_residual;

  return (
    <div className="h-full overflow-auto p-4 space-y-4" data-testid="page-odoo-bill-detail">
      <div className="flex items-center gap-3 flex-wrap">
        <Button variant="ghost" onClick={() => navigate("/purchase-flow")} data-testid="button-back">
          <ArrowLeft className="w-4 h-4 mr-2" /> Back
        </Button>
        <Separator orientation="vertical" className="h-6" />
        <div className="flex items-center gap-2">
          <Receipt className="w-5 h-5" />
          <h1 className="text-xl font-semibold" data-testid="text-bill-name">
            {bill.name || "Draft"}
            {bill.ref && (
              <span className="text-sm font-normal text-muted-foreground ml-1.5" data-testid="text-bill-ref">({bill.ref})</span>
            )}
          </h1>
        </div>
        <Badge variant={stateVariants[bill.state] || "outline"} data-testid="badge-bill-state">
          {stateLabels[bill.state] || bill.state}
        </Badge>
        <Badge variant={paymentVariants[bill.payment_state] || "outline"} data-testid="badge-payment-state">
          {paymentLabels[bill.payment_state] || bill.payment_state}
        </Badge>
      </div>

      {bill.invoice_origin && (
        <div className="flex items-center gap-2 text-sm text-muted-foreground" data-testid="text-source">
          <span>Source:</span>
          {sourcePO ? (
            <Button variant="ghost" className="p-0 h-auto text-sm text-primary underline underline-offset-2" onClick={() => navigate(`/purchase-flow/orders/${sourcePO.id}`)} data-testid="link-source-po">
              {sourcePO.name}
            </Button>
          ) : (
            <span>{bill.invoice_origin}</span>
          )}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card data-testid="card-bill-total">
          <CardContent className="p-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground mb-1">
              <DollarSign className="w-4 h-4" /> Bill Total
            </div>
            <p className="text-2xl font-bold font-mono">${bill.amount_total?.toFixed(2)}</p>
            <div className="flex items-center gap-3 mt-1 text-xs text-muted-foreground flex-wrap">
              <span>Untaxed: ${bill.amount_untaxed?.toFixed(2)}</span>
              <span>Tax: ${bill.amount_tax?.toFixed(2)}</span>
            </div>
          </CardContent>
        </Card>

        <Card data-testid="card-payment">
          <CardContent className="p-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground mb-1">
              <CreditCard className="w-4 h-4" /> Payment
            </div>
            <p className="text-2xl font-bold font-mono">${amountPaid.toFixed(2)}</p>
            <div className="flex items-center gap-2 mt-1 text-xs flex-wrap">
              {bill.amount_residual > 0.01 ? (
                <span className="text-destructive font-medium">Outstanding: ${bill.amount_residual?.toFixed(2)}</span>
              ) : bill.state === "posted" ? (
                <span className="text-green-600 dark:text-green-400 font-medium">Fully Paid</span>
              ) : (
                <span className="text-muted-foreground">{stateLabels[bill.state] || bill.state}</span>
              )}
            </div>
          </CardContent>
        </Card>

        <Card data-testid="card-line-count">
          <CardContent className="p-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground mb-1">
              <Package className="w-4 h-4" /> Line Items
            </div>
            <p className="text-2xl font-bold">{lines.length}</p>
          </CardContent>
        </Card>

        <Card data-testid="card-dates">
          <CardContent className="p-4">
            <div className="flex items-center gap-2 text-sm text-muted-foreground mb-1">
              <Calendar className="w-4 h-4" /> Dates
            </div>
            <p className="text-sm mt-1"><span className="text-muted-foreground">Bill Date:</span> {bill.invoice_date ? new Date(bill.invoice_date).toLocaleDateString() : "-"}</p>
            <p className="text-sm"><span className="text-muted-foreground">Due Date:</span> {bill.invoice_date_due ? new Date(bill.invoice_date_due).toLocaleDateString() : "-"}</p>
            <p className="text-sm"><span className="text-muted-foreground">Created:</span> {bill.create_date ? new Date(bill.create_date).toLocaleDateString() : "-"}</p>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <div className="lg:col-span-2 space-y-4">
          {lines.length > 0 && (
            <Card data-testid="card-bill-lines">
              <CardHeader className="pb-3">
                <CardTitle className="flex items-center gap-2 text-base">
                  <Package className="w-4 h-4" /> Line Items ({lines.length})
                </CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                <div className="overflow-x-auto">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Product / Description</TableHead>
                        <TableHead>Account</TableHead>
                        <TableHead className="text-right">Quantity</TableHead>
                        <TableHead className="text-right">Unit Price</TableHead>
                        <TableHead className="text-right">Discount</TableHead>
                        <TableHead className="text-right">Subtotal</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {lines.map((line: any) => (
                        <TableRow key={line.id} data-testid={`row-line-${line.id}`}>
                          <TableCell>
                            <div>
                              <span className="font-medium">{Array.isArray(line.product_id) ? line.product_id[1] : (line.name || "N/A")}</span>
                              {line.name && Array.isArray(line.product_id) && line.name !== line.product_id[1] && (
                                <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{line.name}</p>
                              )}
                            </div>
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground">
                            {Array.isArray(line.account_id) ? line.account_id[1] : "-"}
                          </TableCell>
                          <TableCell className="text-right font-mono">{line.quantity}</TableCell>
                          <TableCell className="text-right font-mono">${line.price_unit?.toFixed(2)}</TableCell>
                          <TableCell className="text-right font-mono">
                            {line.discount > 0 ? `${line.discount}%` : "-"}
                          </TableCell>
                          <TableCell className="text-right font-mono font-semibold">${line.price_subtotal?.toFixed(2)}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
                <div className="flex items-center justify-end gap-4 p-3 border-t text-sm flex-wrap">
                  <span className="text-muted-foreground">Subtotal:</span>
                  <span className="font-mono font-semibold">${bill.amount_untaxed?.toFixed(2)}</span>
                  <span className="text-muted-foreground">Tax:</span>
                  <span className="font-mono">${bill.amount_tax?.toFixed(2)}</span>
                  <span className="text-muted-foreground">Total:</span>
                  <span className="font-mono font-bold text-base">${bill.amount_total?.toFixed(2)}</span>
                </div>
              </CardContent>
            </Card>
          )}
        </div>

        <div className="space-y-4">
          <Card data-testid="card-vendor">
            <CardHeader className="pb-3">
              <CardTitle className="flex items-center gap-2 text-base">
                <User className="w-4 h-4" /> Vendor
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <p className="font-semibold" data-testid="text-vendor-name">{vendorName}</p>
              {partner && (
                <>
                  {partner.email && (
                    <div className="flex items-center gap-2 text-sm">
                      <Mail className="w-3.5 h-3.5 text-muted-foreground" />
                      <span>{partner.email}</span>
                    </div>
                  )}
                  {(partner.phone || partner.mobile) && (
                    <div className="flex items-center gap-2 text-sm">
                      <Phone className="w-3.5 h-3.5 text-muted-foreground" />
                      <span>{partner.phone || partner.mobile}</span>
                    </div>
                  )}
                  {(partner.street || partner.city) && (
                    <div className="flex items-start gap-2 text-sm">
                      <MapPin className="w-3.5 h-3.5 text-muted-foreground mt-0.5" />
                      <div>
                        {partner.street && <p>{partner.street}</p>}
                        {partner.street2 && <p>{partner.street2}</p>}
                        <p>
                          {[partner.city, Array.isArray(partner.state_id) ? partner.state_id[1] : null, partner.zip]
                            .filter(Boolean).join(", ")}
                        </p>
                        {Array.isArray(partner.country_id) && <p>{partner.country_id[1]}</p>}
                      </div>
                    </div>
                  )}
                  {partner.vat && (
                    <div className="flex items-center gap-2 text-sm">
                      <Hash className="w-3.5 h-3.5 text-muted-foreground" />
                      <span>VAT: {partner.vat}</span>
                    </div>
                  )}
                </>
              )}
            </CardContent>
          </Card>

          <Card data-testid="card-timeline">
            <CardHeader className="pb-3">
              <CardTitle className="flex items-center gap-2 text-base">
                <Clock className="w-4 h-4" /> Timeline
              </CardTitle>
            </CardHeader>
            <CardContent>
              <BillTimeline bill={bill} />
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

function BillTimeline({ bill }: { bill: any }) {
  const events: { date: string; icon: typeof CircleDot; color: string; title: string; detail: string }[] = [];

  if (bill.create_date) {
    events.push({ date: bill.create_date, icon: CircleDot, color: "text-primary", title: "Bill Created", detail: bill.name || "Draft" });
  }
  if (bill.state === "posted" && bill.invoice_date) {
    events.push({ date: bill.invoice_date, icon: CircleCheck, color: "text-blue-500 dark:text-blue-400", title: "Bill Posted", detail: `Total: $${bill.amount_total?.toFixed(2)}` });
  }
  if (bill.state === "cancel" && bill.write_date) {
    events.push({ date: bill.write_date, icon: XCircle, color: "text-destructive", title: "Bill Cancelled", detail: "" });
  }
  if (bill.state === "posted" && bill.payment_state === "paid" && bill.write_date) {
    events.push({ date: bill.write_date, icon: CircleCheck, color: "text-green-600 dark:text-green-400", title: "Payment Made", detail: `$${bill.amount_total?.toFixed(2)}` });
  } else if (bill.state === "posted" && bill.payment_state === "partial" && bill.write_date) {
    events.push({ date: bill.write_date, icon: CircleDot, color: "text-amber-500 dark:text-amber-400", title: "Partial Payment", detail: `Paid: $${(bill.amount_total - bill.amount_residual)?.toFixed(2)}` });
  }

  events.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  return (
    <div className="relative pl-5">
      <div className="absolute left-[9px] top-1 bottom-1 w-px bg-border" />
      {events.map((evt, idx) => {
        const Icon = evt.icon;
        return (
          <div key={idx} className="relative pb-5 last:pb-0" data-testid={`timeline-event-${idx}`}>
            <div className="absolute left-[-13px] top-0.5 w-5 h-5 rounded-full bg-background flex items-center justify-center">
              <Icon className={`w-4 h-4 ${evt.color}`} />
            </div>
            <div className="ml-3">
              <p className="text-sm font-medium">{evt.title}</p>
              {evt.detail && <p className="text-xs text-muted-foreground">{evt.detail}</p>}
              <p className="text-xs text-muted-foreground mt-0.5">{new Date(evt.date).toLocaleString()}</p>
            </div>
          </div>
        );
      })}
      {events.length === 0 && <p className="text-sm text-muted-foreground text-center py-4">No events</p>}
    </div>
  );
}

